/**
 * Paxeer SDK — Contract Instances
 * Auto-generated by scripts/generate-sdk.ts
 *
 * Usage:
 *   import { getPECORContracts, getV4Contracts } from "./sdk/contracts";
 *   const { pecor, quoter, vault, oracle, orders } = getPECORContracts(signer);
 */

import { ethers } from "ethers";
import { CONTRACTS, RPC_URL } from "./addresses";
import {
    PECOR_ABI, PECOR_ORDERS_ABI, PECOR_STOP_ORDERS_ABI, PECOR_QUOTER_ABI, PECOR_VAULT_ABI,
    PRICE_ORACLE_ABI, ORACLE_HUB_ABI, PECOR_ROUTER_ABI,
    SIDIORA_POOL_REGISTRY_ABI, SIDIORA_QUOTER_ABI, SIDIORA_ROUTER_ABI,
    SIDIORA_POOL_ABI, ERC20_ABI,
} from "./abis";

export type SignerOrProvider = ethers.Signer | ethers.Provider;

export function getDefaultProvider(): ethers.JsonRpcProvider {
    return new ethers.JsonRpcProvider(RPC_URL);
}

// ─── V3 Core ──────────────────────────────────────────────────────────────────
export interface PECORContracts {
    pecor: ethers.Contract;
    orders: ethers.Contract;
    stopOrders: ethers.Contract;
    quoter: ethers.Contract;
    vault: ethers.Contract;
    oracle: ethers.Contract;
}

export function getPECORContracts(signerOrProvider: SignerOrProvider): PECORContracts {
    return {
        pecor: new ethers.Contract(CONTRACTS.PECOR, PECOR_ABI, signerOrProvider),
        orders: new ethers.Contract(CONTRACTS.PECOROrders, PECOR_ORDERS_ABI, signerOrProvider),
        stopOrders: new ethers.Contract(CONTRACTS.PECORStopOrders, PECOR_STOP_ORDERS_ABI, signerOrProvider),
        quoter: new ethers.Contract(CONTRACTS.PECORQuoter, PECOR_QUOTER_ABI, signerOrProvider),
        vault: new ethers.Contract(CONTRACTS.PECORVault, PECOR_VAULT_ABI, signerOrProvider),
        oracle: new ethers.Contract(CONTRACTS.PriceOracle, PRICE_ORACLE_ABI, signerOrProvider),
    };
}

// ─── V4 Router ────────────────────────────────────────────────────────────────
export interface V4Contracts {
    router: ethers.Contract;
    oracleHub: ethers.Contract;
}

export function getV4Contracts(signerOrProvider: SignerOrProvider): V4Contracts {
    return {
        router: new ethers.Contract(CONTRACTS.PECORRouter, PECOR_ROUTER_ABI, signerOrProvider),
        oracleHub: new ethers.Contract(CONTRACTS.OracleHub, ORACLE_HUB_ABI, signerOrProvider),
    };
}

// ─── Sidiora ──────────────────────────────────────────────────────────────────
export interface SidioraContracts {
    registry: ethers.Contract;
    quoter: ethers.Contract;
    router: ethers.Contract;
}

export function getSidioraContracts(signerOrProvider: SignerOrProvider): SidioraContracts {
    return {
        registry: new ethers.Contract(CONTRACTS.PoolRegistry, SIDIORA_POOL_REGISTRY_ABI, signerOrProvider),
        quoter: new ethers.Contract(CONTRACTS.Quoter, SIDIORA_QUOTER_ABI, signerOrProvider),
        router: new ethers.Contract(CONTRACTS.Router, SIDIORA_ROUTER_ABI, signerOrProvider),
    };
}

export function getSidioraPool(poolAddress: string, signerOrProvider: SignerOrProvider): ethers.Contract {
    return new ethers.Contract(poolAddress, SIDIORA_POOL_ABI, signerOrProvider);
}

export function getERC20(tokenAddress: string, signerOrProvider: SignerOrProvider): ethers.Contract {
    return new ethers.Contract(tokenAddress, ERC20_ABI, signerOrProvider);
}

/** Read-only convenience: all contracts connected to the public Paxeer RPC */
export function getReadOnlyContracts() {
    const provider = getDefaultProvider();
    return {
        ...getPECORContracts(provider),
        ...getV4Contracts(provider),
        ...getSidioraContracts(provider),
        provider,
    };
}
